<?php
require_once __DIR__ . '/../../include/auth_user.php';
$role='User'; $area='user'; $activeMenu='status'; $pageTitle='Detail Status Surat';
$id=max(0,(int)($_GET['id'] ?? 0));
$stmt=$conn->prepare('SELECT s.*, u.nama AS pembuat_nama FROM surat s JOIN users u ON u.id=s.created_by WHERE s.id=? LIMIT 1'); $stmt->bind_param('i',$id); $stmt->execute(); $letter=$stmt->get_result()->fetch_assoc(); $stmt->close();
if (!$letter) { $_SESSION['flash']=['type'=>'error','message'=>'Data surat tidak ditemukan.']; header('Location: '.BASE_URL.'/'.$area.'/status_surat/index.php'); exit; }
$logsStmt=$conn->prepare('SELECT l.*, u.nama AS pengubah_nama FROM surat_status_logs l JOIN users u ON u.id=l.changed_by WHERE l.surat_id=? ORDER BY l.changed_at DESC,l.id DESC'); $logsStmt->bind_param('i',$id); $logsStmt->execute(); $logs=$logsStmt->get_result();
$validStatuses=$letter['jenis_surat']==='Masuk'?['Diterima','Menunggu Disposisi','Dalam Proses','Selesai','Ditolak']:['Draft','Dalam Proses','Selesai','Dibatalkan'];
$folder=$letter['jenis_surat']==='Masuk'?'surat_masuk':'surat_keluar';
require __DIR__ . '/../../include/header.php';
?>
<div class="page-heading"><div><h1>Status Surat</h1><p>Pantau perubahan status dan tindak lanjut surat.</p><div class="breadcrumbs"><a href="<?= BASE_URL ?>/<?= $area ?>/dashboard.php">Dashboard</a><span>›</span><a href="<?= BASE_URL ?>/<?= $area ?>/status_surat/index.php">Status Surat</a><span>›</span>Detail</div></div><a class="button button-light" href="<?= BASE_URL ?>/<?= $area ?>/<?= $folder ?>/detail.php?id=<?= $id ?>">Detail Surat</a></div>
<div class="status-page-grid"><div class="status-main-column"><section class="panel"><div class="panel-heading"><div><h2><?= htmlspecialchars($letter['nomor_surat'],ENT_QUOTES,'UTF-8') ?></h2><p><?= htmlspecialchars($letter['perihal'],ENT_QUOTES,'UTF-8') ?></p></div><span class="status-badge <?= $letter['status']==='Selesai'?'status-done':($letter['status']==='Dalam Proses'?'status-progress':(in_array($letter['status'],['Ditolak','Dibatalkan'],true)?'status-rejected':'status-waiting')) ?>"><?= htmlspecialchars($letter['status'],ENT_QUOTES,'UTF-8') ?></span></div><dl class="compact-detail"><div><dt>Jenis Surat</dt><dd><?= $letter['jenis_surat']==='Masuk'?'Surat Masuk':'Surat Keluar' ?></dd></div><div><dt>Tanggal Surat</dt><dd><?= date('d-m-Y',strtotime($letter['tanggal_surat'])) ?></dd></div><div><dt>Pengirim</dt><dd><?= htmlspecialchars($letter['pengirim']?:'-',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Tujuan</dt><dd><?= htmlspecialchars($letter['tujuan']?:'-',ENT_QUOTES,'UTF-8') ?></dd></div></dl><a class="button button-dark <?= empty($letter['uploaded_file']) ? 'is-hidden' : '' ?>" href="<?= BASE_URL ?>/proses/file_surat.php?id=<?= $id ?>&amp;mode=view">Lihat Lampiran</a></section>
<section class="panel"><div class="panel-heading"><div><h2>Timeline Status Surat</h2><p>Riwayat perubahan disusun berdasarkan waktu terbaru.</p></div></div><?php if($logs->num_rows>0): ?><div class="timeline"><?php while($log=$logs->fetch_assoc()): ?><div class="timeline-item"><span class="timeline-dot"></span><div class="timeline-content"><div class="timeline-meta"><strong><?= htmlspecialchars($log['status_baru'],ENT_QUOTES,'UTF-8') ?></strong><time><?= date('d-m-Y H:i',strtotime($log['changed_at'])) ?></time></div><p><?= $log['status_lama']?htmlspecialchars($log['status_lama'],ENT_QUOTES,'UTF-8').' → ':'' ?><?= htmlspecialchars($log['status_baru'],ENT_QUOTES,'UTF-8') ?></p><?php if($log['catatan']): ?><p class="timeline-note"><?= htmlspecialchars($log['catatan'],ENT_QUOTES,'UTF-8') ?></p><?php endif; ?><small>Diubah oleh <?= htmlspecialchars($log['pengubah_nama'],ENT_QUOTES,'UTF-8') ?></small></div></div><?php endwhile; ?></div><?php else: ?><div class="empty-state">Belum ada riwayat status surat.</div><?php endif; ?></section><?php require __DIR__ . '/../../include/disposisi_surat_panel.php'; ?></div>
<aside class="panel status-detail-panel"><div class="panel-heading"><div><h2>Informasi Pemantauan</h2><p>Data terkini surat.</p></div></div><dl class="compact-detail"><div><dt>Status aktif</dt><dd><?= htmlspecialchars($letter['status'],ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Dicatat oleh</dt><dd><?= htmlspecialchars($letter['pembuat_nama'],ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Diperbarui</dt><dd><?= date('d-m-Y H:i',strtotime($letter['updated_at'])) ?></dd></div><div><dt>Arsip</dt><dd><?= $letter['status']==='Selesai'?'Masuk arsip otomatis':'Belum masuk arsip' ?></dd></div></dl>
<?php if($role==='Admin'): ?><hr class="section-rule"><div class="status-update-box"><h3>Ubah Status Surat</h3><form class="form-stack" method="post" action="<?= BASE_URL ?>/proses/status_update.php"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token'],ENT_QUOTES,'UTF-8') ?>"><input type="hidden" name="id" value="<?= $id ?>"><label for="status_baru">Status Baru</label><select id="status_baru" name="status_baru" required><?php foreach($validStatuses as $st): ?><option value="<?= htmlspecialchars($st,ENT_QUOTES,'UTF-8') ?>" <?= $letter['status']===$st?'selected':'' ?>><?= htmlspecialchars($st,ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select><label for="catatan">Catatan Perubahan</label><textarea id="catatan" name="catatan" rows="4" maxlength="500" placeholder="Alasan atau keterangan tindak lanjut..."></textarea><button class="button button-dark button-full" type="submit">Simpan Perubahan Status</button></form><small class="field-help">Status Selesai akan memasukkan surat ke arsip. Jika diubah kembali ke status lain, arsip aktifnya akan dikeluarkan.</small></div><?php else: ?><div class="empty-state">Perubahan status dilakukan oleh Admin.</div><?php endif; ?></aside></div>
<?php require __DIR__ . '/../../include/footer.php'; ?>
